query studentDetailQuery($mnumber: String!, $term: String!, $year: Int!) {
  studentsSingle(where: {mnumber: {eq: $mnumber}}) {
    first_name
    last_name
    middle_name
    suffix
    email
    birthdate
    gender
    cell_phone
    race
    residency
    citizenship
    mnumber
    termInfo: academic_info(term: $term, year: $year) {
      admit_code
      academic_standing {
        code
        description
        __typename
      }
      admit_term {
        code
        description
        __typename
      }
      admit_year
      msu_attempted_hours
      msu_earned_hours
      msu_gpa
      msu_quality_points
      overall_attempted_hours
      overall_earned_hours
      overall_gpa
      overall_quality_points
      __typename
    }
    gpaTrend: academic_info {
      msu_gpa
      overall_gpa
      term {
        code
        description
        __typename
      }
      year
      __typename
    }
    advisors {
      advisor_mnumber
      term {
        code
        description
        __typename
      }
      year
      advisor {
        first_name
        last_name
        mnumber
        user {
          email
          __typename
        }
        __typename
      }
      __typename
    }
    programs {
      term {
        code
        description
        __typename
      }
      year
      type
      level
      program {
        code
        description
        __typename
      }
      __typename
    }
    __typename
  }
}

